gisterAction\", \"name\": \"Register for a Spiritual Retreat\", \"target\": \"{action_url}\" }, { \"@type\": \"ViewAction\", \"name\": \"Explore Site History & Visiting Info\", \"target\": \"{action_url}\" }, { \"@type\": \"CommunicateAction\", \"name\": \"Contact Visitor Services\", \"target\": \"{action_url}\" }, { \"@type\": \"CommunicateAction\", \"name\": \"Browse Religious Gift Shop\", \"target\": \"{action_url}\" }]\n}", "html": "<main itemscope itemtype=\"https://schema.org/PlaceOfWorship\">\n  <h1 itemprop=\"name\">{name}</h1>\n  <span itemprop=\"telephone\">{phone}</span>\n  <div itemprop=\"address\" itemscope itemtype=\"https://schema.org/PostalAddress\">\n    <span itemprop=\"addressLocality\">{city}</span>, <span itemprop=\"addressRegion\">{state}</span>\n  </div>\n  <div itemprop=\"aggregateRating\" itemscope itemtype=\"https://schema.org/AggregateRating\">\n    <span itemprop=\"ratingValue\">{rating}</span>★ (<span itemprop=\"reviewCount\">{review_count}</span>)\n  </div>\n</main>", "profile": [{"kind": "header", "name": "{business_name}", "subtitle": "Religious Destination · {credential_line}", "initials": "{initials}", "badges": ["Verified"], "rating": "{rating}", "ratingCount": "{review_count}", "chips": ["{location_chip}"], "bio": "{bio}", "ctas": ["{primary_cta}", "{secondary_cta}"]}, {"kind": "infoCards", "cards": [{"title": "Contact", "lines": ["{phone}", "{city}, {state}", "{website}"], "chips": ["{social_chips}"]}, {"title": "Credentials", "lines": ["{license_line}", "{memberships_line}"], "chips": ["{designation_chips}"]}]}, {"kind": "lines", "title": "About", "lines": ["{about_line_1}", "{about_line_2}"]}, {"kind": "roster", "title": "Professionals", "members": [{"initials": "{m_initials}", "name": "{m_name}", "meta": "{m_meta}"}], "note": "Roster ranked by search rank score."}, {"kind": "stats", "title": "Track record", "stats": [{"value": "{stat1}", "label": "{stat1_label}"}, {"value": "{stat2}", "label": "{stat2_label}"}]}, {"kind": "ser